import * as z from "zod/v4";
import { SitemapOptionsSchema } from "./schema.js";
// @internal
export const validateOptions = (site, opts) => {
	const result = SitemapOptionsSchema.parse(opts);
	z.object({
		site: z.string().optional(),
		canonicalURL: z.string().optional()
	}).refine((options) => options.site || options.canonicalURL, { message: "Required `site` astro.config option or `canonicalURL` integration option" }).parse({
		site,
		canonicalURL: result.canonicalURL
	});
	return result;
};
